import{_ as s,o as t,c as i,a2 as o}from"./chunks/framework.DMvgf4hZ.js";const k=JSON.parse('{"title":"版本发布与 CI","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/release.md","filePath":"deploy/release.md","lastUpdated":1794885765000}'),a={name:"deploy/release.md"};function d(l,e,n,p,c,r){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="版本发布与-ci" tabindex="-1">版本发布与 CI <a class="header-anchor" href="#版本发布与-ci" aria-label="Permalink to &quot;版本发布与 CI&quot;">​</a></h1><h2 id="通过版本标签自动发布" tabindex="-1">通过版本标签自动发布 <a class="header-anchor" href="#通过版本标签自动发布" aria-label="Permalink to &quot;通过版本标签自动发布&quot;">​</a></h2><p>发布直接使用现有提交上的 <code>vX.Y.Z</code> 标签，无需 Git Flow 或 release 分支。</p><ol><li>提交要发布的代码，在 SourceTree 中选中该提交，点击 <strong>标签</strong>。</li><li>填写完整标签名，例如 <code>v2.0.0</code>，确认标签指向要发布的提交。</li><li>在左侧标签列表右键这个新标签，选择 <strong>推送标签</strong>，目标选择正式仓库 <code>origin</code>。只推送本次标签，不勾选“推送所有标签”。</li></ol><p>推送标签会一并上传它所引用的提交，无需创建或推送发布分支。标签推送私有仓 <code>origin</code>（<code>Scenoria/toonflow</code>）即触发 <strong>Release Toonflow</strong>：构建六种桌面目标与 Android ARM64，全部成功后把产物跨仓发布到公开仓 <code>dolfly/toonflow</code> 的 Releases，公开仓只接收产物、不暴露源码。</p><p>也可在仓库终端执行下面两条命令（将 <code>2.0.0</code> 换成本次版本）：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v2.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Release v2.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-follow-tags</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refs/tags/v2.0.0:refs/tags/v2.0.0</span></span></code></pre></div><p>版本格式为小写 <code>v</code> 加 <code>X.Y.Z</code>；轻量标签和附注标签均支持。使用新的版本号，不覆盖已有标签。构建失败时，在 Actions 中查看日志；代码不变可重跑任务，修改代码后使用新版本号。</p><h2 id="一次构建全部平台" tabindex="-1">一次构建全部平台 <a class="header-anchor" href="#一次构建全部平台" aria-label="Permalink to &quot;一次构建全部平台&quot;">​</a></h2><p>在 GitHub 仓库打开 <strong>Actions → Release Toonflow → Run workflow</strong>，选择要发布的可信分支，填写版本号（例如 <code>2.0.1</code>），将 <code>ref</code> 留空后运行。推送 <code>vX.Y.Z</code> 标签同样会触发发布。包含任一种 Mac 的签名构建要求 <code>ref</code> 与触发工作流的分支或标签指向同一提交，不允许借此切换到其他提交；在 Debug 工作流仅构建 Windows、Linux 或 Android 时可指定其他 <code>ref</code>。</p><p>工作流使用各系统与架构的原生运行器构建，全部成功后统一上传到对应 GitHub Release：</p><table tabindex="0"><thead><tr><th>平台</th><th>安装包</th><th>更新文件</th></tr></thead><tbody><tr><td>Windows x64</td><td><code>toonflow-&lt;版本号&gt;-Setup.exe</code></td><td><code>stable-win-x64-*</code></td></tr><tr><td>Windows ARM64</td><td><code>toonflow-&lt;版本号&gt;-win-arm64-Setup.exe</code></td><td><code>stable-win-arm64-*</code></td></tr><tr><td>macOS Intel</td><td><code>toonflow-&lt;版本号&gt;-macos-x64.dmg</code></td><td><code>stable-macos-x64-*</code></td></tr><tr><td>macOS Apple Silicon</td><td><code>toonflow-&lt;版本号&gt;-macos-arm64.dmg</code></td><td><code>stable-macos-arm64-*</code></td></tr><tr><td>Linux x64</td><td><code>toonflow-&lt;版本号&gt;-linux-x64.deb</code></td><td><code>stable-linux-x64-*</code></td></tr><tr><td>Linux ARM64</td><td><code>toonflow-&lt;版本号&gt;-linux-arm64.deb</code></td><td><code>stable-linux-arm64-*</code></td></tr><tr><td>Android ARM64</td><td><code>toonflow-&lt;版本号&gt;-android-arm64.apk</code></td><td>APK 随 Release 发布，不使用桌面更新清单</td></tr></tbody></table><p>各桌面目标包含完整更新包 <code>.tar.zst</code>、更新清单 <code>*-update.json</code>，以及 <strong>GitHub 最新发布版 → 当前版本</strong>的 <code>&lt;平台前缀&gt;-&lt;旧 hash&gt;.patch</code>。首次发布找不到该目标清单（HTTP 404）时只生成安装包和完整更新包；Intel Mac 首次遇到旧 SDK 清单时也只生成统一 SDK 的首版完整包。其他网络错误、无效清单或缺失 patch 会中止构建。版本号必须高于更新源中的上一版。</p><p>构建固定使用 GitHub Releases 的 <code>releases/latest/download</code> 读取上一版清单及完整包，用于生成补丁。CI 通过仓库变量 <code>TOONFLOW_RELEASE_BASE_URL</code> 指定基线地址（指向产物所在公开仓的 <code>releases/latest/download</code>），本机构建默认使用 <code>HBAI-Ltd/Toonflow-app</code>。此地址写入 SDK 的构建配置，不受客户端设置影响；客户端运行时在“设置 → 关于”选择更新源，默认使用官方源 <code>https://api.toonflow.net/version/desktopUpdates</code>，也可切换到 GitHub Releases。开发者选项可保存一个自定义更新文件目录地址，保存后会出现在“关于”的更新源下拉框。Release 工作流会上传安装包和更新文件到 GitHub Release，再通过配置的托管接口登记六个桌面目标；使用独立更新服务时按其说明单独同步，见<a href="./updates.html">客户端更新与增量发布</a>。</p><p><a href="https://github.com/dolfly/toonflow/blob/master/.github/workflows/debug.yml" target="_blank" rel="noreferrer">Debug 工作流</a> 可单独选择平台或全部平台，产物保留 7 天，不创建 Release。默认只打完整包，勾选 <code>generatePatch</code> 可验证增量构建。CI 构建和归档检查不等于已验证真实安装、GUI 启动或 macOS Gatekeeper。</p><h2 id="仓库与发布链路" tabindex="-1">仓库与发布链路 <a class="header-anchor" href="#仓库与发布链路" aria-label="Permalink to &quot;仓库与发布链路&quot;">​</a></h2><p>源码私有化后采用“私有源码 + 公开产物”两个仓库：</p><table tabindex="0"><thead><tr><th>仓库</th><th>可见性</th><th>分支</th><th>作用</th></tr></thead><tbody><tr><td><code>Scenoria/toonflow</code></td><td>私有</td><td><code>main</code>（默认）/ <code>master</code> / <code>develop</code> / <code>gh-pages</code></td><td>源码与 CI：<code>main</code> 是 fork 改造的发布分支，<code>master</code>、<code>develop</code> 只镜像上游</td></tr><tr><td><code>dolfly/toonflow</code></td><td>公开</td><td><code>master</code> / <code>develop</code> / <code>gh-pages</code></td><td>上游镜像、文档站与安装包下载</td></tr></tbody></table><ul><li><code>master</code>、<code>develop</code> 与上游 <code>HBAI-Ltd/Toonflow-app</code> 保持零偏差，由 <code>sync-upstream</code> 工作流每日同步（私有仓与公开仓同时推送）。</li><li>文档站由私有仓 <code>docs.yml</code> 构建后强制推送到公开仓的 <code>gh-pages</code>，站点地址 <code>https://dolfly.github.io/toonflow/</code> 不变。</li><li>安装包由私有仓 <code>release.yml</code> 构建，跨仓发布到 <code>dolfly/toonflow</code> 的 Releases；公开仓只放产物，不暴露源码。</li><li>容器镜像默认发布到 <code>ghcr.io/scenoria/toonflow</code>；需要同时维护 <code>ghcr.io/dolfly/toonflow</code> 时，把仓库变量 <code>DOLFLY_IMAGE_MIRROR</code> 设为 <code>true</code>。</li><li>跨仓推送使用仓库 Secret <code>SCENORIA_PUBLISH_TOKEN</code>（对 <code>dolfly</code> 账号下目标仓库有写权限的 PAT）：文档站需要 <code>contents:write</code>，跨仓发布 Release 需要 <code>contents:write</code>，镜像镜像需要 <code>write:packages</code>。未配置时各工作流会跳过跨仓发布并给出告警，不会静默成功。</li></ul><h2 id="windows-代码签名" tabindex="-1">Windows 代码签名 <a class="header-anchor" href="#windows-代码签名" aria-label="Permalink to &quot;Windows 代码签名&quot;">​</a></h2><p>Windows 安装器和自有辅助 EXE 会写入产品、发布者与当前构建版本信息。默认没有签名证书，构建会明确提示产物未签名；版本信息不能代替数字签名，也不代表已通过 Defender 检测。</p><p>在有代码签名证书及匹配私钥的 Windows 构建机上，将证书安装到当前用户的 <code>My</code> 证书库，安装 Windows SDK 的 SignTool，并在执行现有打包命令前设置：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windowsSigningThumbprint </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;证书的40位十六进制指纹&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">windowsSignToolPath </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;C:\\Program Files (x86)\\Windows Kits\\10\\bin\\实际SDK版本\\x64\\signtool.exe&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bun run package:desktop</span></span></code></pre></div><p>SignTool 已在 PATH 时可省略 <code>windowsSignToolPath</code>；指定路径时必须使用绝对路径，避免不同构建阶段的工作目录影响工具选择。未设置 <code>windowsSigningThumbprint</code> 才会跳过签名，显式空字符串、空白或无效指纹均报错。签名采用 SHA-256 与 RFC 3161 时间戳，默认使用 <code>http://timestamp.digicert.com</code>，可通过 <code>windowsSigningTimestampUrl</code> 指定证书服务商的时间戳地址。私钥保留在证书库或提供商的硬件中，不向脚本传递证书密码。</p><p>四个自有启动、协议、保存与更新辅助程序在 SDK 生成更新归档、Hash 和补丁前完成签名；安装检测程序、NSIS 内嵌卸载器和最终安装包也会签名并验证。NSIS 打包使用归档中的更新助手，并校验归档内四个辅助程序的版本；启用签名时还校验其签名、证书指纹和时间戳，不能用未签名旧归档只重签外壳。第三方文件保留其原有签名。配置了证书指纹后，证书、时间戳或签名验证失败均中止打包，不回退为未签名产物；最终 EXE 在暂存目录完成签名后才替换产物，失败不覆盖已有安装包。当前 GitHub 托管 Windows 运行器尚未配置证书，仍输出未签名包；启用 CI 签名需要先提供可用的签名身份。</p><p>签名接入与编译通过不等于误报已解除。Defender 已检测的原始文件需结合保护历史记录复核，必要时通过 <a href="https://www.microsoft.com/en-us/wdsi/filesubmission" target="_blank" rel="noreferrer">Microsoft Security Intelligence</a> 以软件开发者身份提交分析。</p><h2 id="macos-自动签名与公证-首次配置" tabindex="-1">macOS 自动签名与公证：首次配置 <a class="header-anchor" href="#macos-自动签名与公证-首次配置" aria-label="Permalink to &quot;macOS 自动签名与公证：首次配置&quot;">​</a></h2><p>在 GitHub 仓库的 <strong>Settings → Secrets and variables → Actions → New repository secret</strong> 添加：</p><table tabindex="0"><thead><tr><th>Secret</th><th>内容</th></tr></thead><tbody><tr><td><code>MACOS_CERTIFICATE_BASE64</code></td><td><code>.p12</code> 文件，包含唯一有效的 <strong>Developer ID Application</strong> 证书及匹配的私钥，编码为 Base64。</td></tr><tr><td><code>MACOS_CERTIFICATE_PASSWORD</code></td><td>导出该 <code>.p12</code> 时设置的非空密码。</td></tr><tr><td><code>MACOS_NOTARIZATION_KEY_ID</code></td><td>App Store Connect 团队 API 密钥的 Key ID。</td></tr><tr><td><code>MACOS_NOTARIZATION_ISSUER_ID</code></td><td>该团队 API 密钥的完整 Issuer ID，不是 Team ID。</td></tr><tr><td><code>MACOS_NOTARIZATION_KEY_BASE64</code></td><td>对应 API 密钥的 <code>.p8</code> 私钥文件，编码为 Base64。</td></tr></tbody></table><p>在 Windows PowerShell 中执行以下命令，把路径替换为本机证书路径。命令只复制到剪贴板，不打印证书内容，也不生成文件；随后粘贴到 <code>MACOS_CERTIFICATE_BASE64</code> 的 Secret 输入框：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::ToBase64String([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::ReadAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;C:\\证书目录\\signing.p12&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Set-Clipboard</span></span></code></pre></div><p>然后单独执行下面的命令，把 <code>.p8</code> 路径替换为本机文件路径，将剪贴板内容保存到 <code>MACOS_NOTARIZATION_KEY_BASE64</code>：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::ToBase64String([</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]::ReadAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;C:\\证书目录\\AuthKey_你的KeyID.p8&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Set-Clipboard</span></span></code></pre></div><p>粘贴保存后可执行 <code>Set-Clipboard -Value &#39;&#39;</code> 清空剪贴板。密码直接填写到 <code>MACOS_CERTIFICATE_PASSWORD</code>，不写进命令、源码或聊天记录。Base64 只是编码，不是加密；P12、P8、Base64、密码均不得提交到公开仓库或上传为构建产物。</p><p>公证使用 App Store Connect <strong>团队 API 密钥</strong>，Key ID、Issuer ID 与 P8 必须对应同一把有权限的密钥。应用与 DMG 复用这把公证密钥，更换签名 P12 不要求同时更换仍有效且有权限的公证 API 密钥。这种认证方式不需要 Apple ID 密码或 Team ID；P12 及其密码用于应用和 DMG 签名。</p><p>配置后，Debug 与 Release 的两种 Mac 构建都会自动导入临时钥匙串，使用 Developer ID Application 签署应用、原生代码与 DMG，并对应用与 DMG 分别提交 Apple 公证、等待通过、附加并验证公证票据。完整更新归档在应用公证后生成；上传前会验证更新归档中应用的签名和公证票据，并核对是否使用本次导入的 Developer ID Application 证书；DMG 会校验签名与公证票据，并挂载检查其中的应用。</p><p>缺少 Secret、没有唯一有效的 Developer ID Application 身份、Apple 拒绝公证或验收失败都会中止构建，不回退为未签名或未公证包。临时 P12 在导入步骤结束后删除；P8 与钥匙串在构建成功、失败或取消后的清理步骤中删除，均放在运行器临时目录。证书 Base64、密码和 P8 Base64 只注入凭据准备步骤，公证 API 标识只额外传给 Mac 构建步骤。公证等待计入工作流现有的 90 分钟超时，超时不会发布。</p><p>公开仓库只从可信的手动操作或 <code>v*</code> 标签触发签名，不接入 <code>pull_request</code> / <code>pull_request_target</code>。请用 GitHub Rulesets 保护发布分支及 <code>v*</code> 标签，并限制仓库写权限；签名构建会执行所选提交的代码，有权修改发布代码或工作流的人也处于 Secrets 的信任边界内。证书导入方式参见 <a href="https://docs.github.com/en/actions/how-tos/deploy/deploy-to-third-party-platforms/sign-xcode-applications" target="_blank" rel="noreferrer">GitHub 官方说明</a>。</p><p>两种 Mac 的 CI 构建强制同时签名与公证，本机构建默认不启用。公证无需上架 App Store，首次打开仍可能出现确认打开互联网下载应用的提示。CI 验收不代替实际 Mac 上从浏览器下载、安装、启动及升级的验证，参见 <a href="https://support.apple.com/en-us/102445" target="_blank" rel="noreferrer">Apple 安全打开应用说明</a>。</p><p>若凭据准备步骤提示未找到唯一有效的签名身份，查看该步骤后续输出的证书类别、有效期和系统诊断。应用与 DMG 需要 <code>Developer ID Application</code>，<code>Developer ID Installer</code>、<code>Apple Development</code>、<code>Apple Distribution</code> 不能替代该身份。若类别正确，仍需检查是否含匹配私钥、是否过期，以及证书信任链；成功导入 P12 不等于存在有效的签名身份。诊断不会打印私钥、密码或证书姓名。</p><h2 id="文档站构建与发布" tabindex="-1">文档站构建与发布 <a class="header-anchor" href="#文档站构建与发布" aria-label="Permalink to &quot;文档站构建与发布&quot;">​</a></h2><p>文档站（本站）由 <code>.github/workflows/docs.yml</code> 构建，产物发布到 <strong><code>gh-pages</code> 分支</strong>，GitHub Pages 从该分支提供服务：</p><ul><li><p>触发条件：推送到 <code>master</code> 且改动涉及 <code>docs-site/**</code> 或 <code>docs/**</code>，或在 Actions 中手动运行。</p></li><li><p>构建：Bun 1.4.3 + <code>bun install --frozen-lockfile</code> + <code>bun run build</code>（工作目录 <code>docs-site/</code>），<code>DOCS_BASE</code> 由仓库名注入，产物为 <code>docs-site/.vitepress/dist</code>。</p></li><li><p>发布：把 <code>dist</code> 内容（含 <code>.nojekyll</code>）以单提交 force push 到 <code>gh-pages</code>，<code>master</code> 上不保存任何构建产物，只有文档源码；PR 只构建不发布。</p></li><li><p>仓库设置：<strong>Settings → Pages → Build and deployment → Source</strong> 选择 <strong>Deploy from a branch</strong>，分支 <code>gh-pages</code>、目录 <code>/</code>。首次开启或从其他来源切换：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">owne</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/toonflow/pages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build_type=legacy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source[branch]=gh-pages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source[path]=/</span></span></code></pre></div></li><li><p>站点地址形如 <code>https://&lt;owner&gt;.github.io/toonflow/</code>。</p></li></ul><p>回滚方式：<code>git revert</code> 对应提交后重新运行 workflow，会重新生成 <code>gh-pages</code>；或对该 workflow 重新运行上一次成功构建。<code>gh-pages</code> 每次强制覆盖，历史只有一条提交，不用于保存版本快照。</p>`,44)])])}const g=s(a,[["render",d]]);export{k as __pageData,g as default};
